//! Interface and file-type rasterizations shared by both rendering backends.
const ui = @import("nanoui").ui;
pub const Icon = enum { status_idle, status_done, status_waiting, status_failed, status_exited, status_working_0, status_working_1, status_working_2, status_working_3, status_working_4, status_working_5, status_working_6, status_working_7, split_right, split_down, diff, zoom, unzoom, minimize, maximize, return_key, paintbrush, sliders, monitor, terminal, keyboard, clipboard, settings, folder, document, code, search, plus, close, left, right, up, down, more, pin, panel, reset, copy, external, check, sun, moon, lock, lock_open, ellipsis, bell, updown, file_verilog, file_markdown, file_c, file_h, file_cpp, file_hpp, file_python, file_tcl, file_console, file_makefile, file_zig, file_json, file_yaml, file_rust, file_javascript, file_typescript };
pub fn draw(ctx: *ui.Context, icon: Icon, size: f32, opacity: f32) void {
    const bg = ctx.theme.background;
    const light = bg.r * 0.299 + bg.g * 0.587 + bg.b * 0.114 > 0.5;
    const asset: struct { key: []const u8, bytes: []const u8 } = switch (icon) {
        .status_idle => if (light) .{ .key = "letty-status-idle-ink", .bytes = @embedFile("interface/status-idle-ink.png") } else .{ .key = "letty-status-idle-light", .bytes = @embedFile("interface/status-idle-light.png") },
        .status_done => if (light) .{ .key = "letty-status-done-ink", .bytes = @embedFile("interface/status-done-ink.png") } else .{ .key = "letty-status-done-light", .bytes = @embedFile("interface/status-done-light.png") },
        .status_waiting => if (light) .{ .key = "letty-status-waiting-ink", .bytes = @embedFile("interface/status-waiting-ink.png") } else .{ .key = "letty-status-waiting-light", .bytes = @embedFile("interface/status-waiting-light.png") },
        .status_failed => if (light) .{ .key = "letty-status-failed-ink", .bytes = @embedFile("interface/status-failed-ink.png") } else .{ .key = "letty-status-failed-light", .bytes = @embedFile("interface/status-failed-light.png") },
        .status_exited => if (light) .{ .key = "letty-status-exited-ink", .bytes = @embedFile("interface/status-exited-ink.png") } else .{ .key = "letty-status-exited-light", .bytes = @embedFile("interface/status-exited-light.png") },
