        .status_working_1 => if (light) .{ .key = "letty-status-working-1-ink", .bytes = @embedFile("interface/status-working-1-ink.png") } else .{ .key = "letty-status-working-1-light", .bytes = @embedFile("interface/status-working-1-light.png") },
        .status_working_2 => if (light) .{ .key = "letty-status-working-2-ink", .bytes = @embedFile("interface/status-working-2-ink.png") } else .{ .key = "letty-status-working-2-light", .bytes = @embedFile("interface/status-working-2-light.png") },
        .status_working_3 => if (light) .{ .key = "letty-status-working-3-ink", .bytes = @embedFile("interface/status-working-3-ink.png") } else .{ .key = "letty-status-working-3-light", .bytes = @embedFile("interface/status-working-3-light.png") },
