        .copy => if (light) .{ .key = "letty-f7-doc-on-doc-ink", .bytes = @embedFile("interface/f7-doc-on-doc-ink.png") } else .{ .key = "letty-f7-doc-on-doc-light", .bytes = @embedFile("interface/f7-doc-on-doc-light.png") },
        .external => if (light) .{ .key = "letty-f7-arrow-up-right-square-ink", .bytes = @embedFile("interface/f7-arrow-up-right-square-ink.png") } else .{ .key = "letty-f7-arrow-up-right-square-light", .bytes = @embedFile("interface/f7-arrow-up-right-square-light.png") },
        .check => if (light) .{ .key = "letty-lucide-check-ink", .bytes = @embedFile("interface/lucide-check-ink.png") } else .{ .key = "letty-lucide-check-light", .bytes = @embedFile("interface/lucide-check-light.png") },
        .sun => if (light) .{ .key = "letty-f7-paintbrush-ink", .bytes = @embedFile("interface/f7-paintbrush-ink.png") } else .{ .key = "letty-f7-paintbrush-light", .bytes = @embedFile("interface/f7-paintbrush-light.png") },
        .moon => if (light) .{ .key = "letty-f7-paintbrush-ink", .bytes = @embedFile("interface/f7-paintbrush-ink.png") } else .{ .key = "letty-f7-paintbrush-light", .bytes = @embedFile("interface/f7-paintbrush-light.png") },
